// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { ProtectedLaunchTokenV1 } from "../launch-protection/ProtectedLaunchTokenV1.sol";

/// @notice River QA (RIVERQA) launch token. Uses the platform protected launch token policy:
/// cumulative 2% recipient inflow cap for the first 300 seconds, trading gated until the
/// initializer starts the launch, and holder-only burn. No owner, mint or tax powers.
contract RiverQaToken is ProtectedLaunchTokenV1 {
    constructor(
        string memory name_,
        string memory symbol_,
        uint256 supply_,
        address initializer_,
        address manager_
    ) ProtectedLaunchTokenV1(name_, symbol_, supply_, initializer_, manager_) {}
}

