// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolIdLibrary} from "@uniswap/v4-core/src/types/PoolId.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {SwapParams,ModifyLiquidityParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";
import {BalanceDelta,BalanceDeltaLibrary} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {StateLibrary} from "@uniswap/v4-core/src/libraries/StateLibrary.sol";
import {TransientStateLibrary} from "@uniswap/v4-core/src/libraries/TransientStateLibrary.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {FullMath} from "@uniswap/v4-core/src/libraries/FullMath.sol";
import {LiquidityAmounts} from "@uniswap/v4-periphery/src/libraries/LiquidityAmounts.sol";
interface IBurnableFeeToken { function burn(uint256) external; }
interface ICreatorLiquidityHook {
    function poolKey() external view returns(PoolKey memory);
    function observedSqrtPriceX96() external view returns(uint160);
    function quoteFees(uint256,bool,bool) external view returns(uint256,uint256,uint256);
}
/// @notice A v4 position with immutable ownership and no discretionary recipient.
/// @dev Only native claim credits supplied by the hook and token dust acquired from them fund deposits.
contract RiverQaLiquidityVault is IUnlockCallback {
    using PoolIdLibrary for PoolKey;
    using BalanceDeltaLibrary for BalanceDelta;
    IPoolManager public immutable poolManager;
    address public immutable hook;
    address public immutable token;
    address public immutable owner;
    uint128 public liquidity;
    uint256 private ownedTokenReserve;
    bytes32 private pending;
    bool private locked;
    error InvalidAction();
    error Unauthorized();
    constructor(IPoolManager manager,address hook_,address token_,address owner_) {
        if(address(manager).code.length==0||hook_!=msg.sender||token_==address(0)||owner_==address(0))revert InvalidAction();
        poolManager=manager;hook=hook_;token=token_;owner=owner_;
    }
    function reinvest(uint256 budget) external returns(uint256 spent,uint128 added) {
        if(msg.sender!=hook||locked)revert Unauthorized();
        uint256 beforeCredit=poolManager.balanceOf(address(this),0);
        if(budget<2||beforeCredit<budget)revert InvalidAction();
        bytes memory result=_run(1,budget,0);
        added=abi.decode(result,(uint128));
        spent=beforeCredit-poolManager.balanceOf(address(this),0);
        if(added==0||spent==0||spent>budget)revert InvalidAction();
        if(budget>spent&&!poolManager.transfer(hook,0,budget-spent))revert InvalidAction();
    }
    function buyback(uint256 budget) external returns(uint256 spent,uint256 burned) {
        if(msg.sender!=hook||locked)revert Unauthorized();
        uint256 beforeCredit=poolManager.balanceOf(address(this),0);
        if(budget==0||beforeCredit<budget)revert InvalidAction();
        burned=abi.decode(_run(4,budget,0),(uint256));
        spent=beforeCredit-poolManager.balanceOf(address(this),0);
        if(burned==0||spent==0||spent>budget)revert InvalidAction();
        if(budget>spent&&!poolManager.transfer(hook,0,budget-spent))revert InvalidAction();
    }
    function claimFees() external returns(uint256 nativeAmount,uint256 tokenAmount) {
        if(msg.sender!=owner||locked)revert Unauthorized();
        if(liquidity==0)revert InvalidAction();
        (nativeAmount,tokenAmount)=abi.decode(_run(3,0,0),(uint256,uint256));
    }
    function refund(uint256 amount) external {
        if (msg.sender != hook || locked) revert Unauthorized();
        if (amount > poolManager.balanceOf(address(this), 0)) revert InvalidAction();
        if (!poolManager.transfer(hook, 0, amount)) revert InvalidAction();
    }
    function _run(uint8 kind,uint256 budget,uint128 amount) private returns(bytes memory result) {
        locked=true;bytes memory payload=abi.encode(kind,budget,amount);pending=keccak256(payload);
        result=poolManager.unlock(payload);pending=0;locked=false;
    }
    function unlockCallback(bytes calldata payload) external returns(bytes memory) {
        if(msg.sender!=address(poolManager)||!locked||pending==0||keccak256(payload)!=pending)revert Unauthorized();
        (uint8 kind,uint256 budget,uint128 amount)=abi.decode(payload,(uint8,uint256,uint128));
        PoolKey memory key=ICreatorLiquidityHook(hook).poolKey();
        if(Currency.unwrap(key.currency0)!=address(0)||Currency.unwrap(key.currency1)!=token||address(key.hooks)!=hook)revert InvalidAction();
        if(kind==1)return abi.encode(_deposit(key,budget));
        if(kind==4)return abi.encode(_buyback(key,budget));
        if(kind!=3)revert InvalidAction();
        poolManager.modifyLiquidity(key,ModifyLiquidityParams(TickMath.minUsableTick(key.tickSpacing),TickMath.maxUsableTick(key.tickSpacing),int256(0),bytes32(0)),"");
        (uint256 nativeAmount,uint256 tokenAmount)=_payAll(key);
        return abi.encode(nativeAmount,tokenAmount);
    }
    function _buyback(PoolKey memory key,uint256 budget) private returns(uint256 burned) {
        if(budget>0.05 ether)revert InvalidAction();
        uint160 twap=ICreatorLiquidityHook(hook).observedSqrtPriceX96();
        (uint160 current,,,) = StateLibrary.getSlot0(poolManager,key.toId());
        if(twap==0||uint256(current)<FullMath.mulDiv(twap,9951,10000)||uint256(current)>FullMath.mulDiv(twap,10049,10000))revert InvalidAction();
        (,uint256 platform,uint256 project)=ICreatorLiquidityHook(hook).quoteFees(budget,false,true);
        if(platform+project>=budget)revert InvalidAction();
        uint256 minOut=FullMath.mulDiv(FullMath.mulDiv(budget-platform-project,twap,uint256(1)<<96),twap,uint256(1)<<96);
        minOut=FullMath.mulDiv(minOut,99,100);
        uint160 limit=uint160(FullMath.mulDiv(twap,9951,10000));
        if(limit<=TickMath.MIN_SQRT_PRICE)limit=TickMath.MIN_SQRT_PRICE+1;
        if(limit>=current)revert InvalidAction();
        poolManager.swap(key,SwapParams(true,-int256(budget),limit),"");
        int256 tokenDelta=TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency1);
        int256 nativeDelta=TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency0);
        if(tokenDelta<=0||uint256(tokenDelta)<minOut||nativeDelta>=0||uint256(-nativeDelta)>budget)revert InvalidAction();
        burned=uint256(tokenDelta);uint256 beforeBalance=IERC20(token).balanceOf(address(this));
        poolManager.take(key.currency1,address(this),burned);
        if(IERC20(token).balanceOf(address(this))!=beforeBalance+burned)revert InvalidAction();
        uint256 beforeSupply=IERC20(token).totalSupply();IBurnableFeeToken(token).burn(burned);
        if(beforeSupply-IERC20(token).totalSupply()!=burned||IERC20(token).balanceOf(address(this))!=beforeBalance)revert InvalidAction();
        poolManager.burn(address(this),0,uint256(-nativeDelta));
        if(TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency0)!=0||TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency1)!=0)revert InvalidAction();
    }
    function _deposit(PoolKey memory key,uint256 budget) private returns(uint128 added) {
        if(budget>0.05 ether)revert InvalidAction();
        uint160 twap=ICreatorLiquidityHook(hook).observedSqrtPriceX96();
        (uint160 current,,,) = StateLibrary.getSlot0(poolManager,key.toId());
        if(twap==0||uint256(current)<FullMath.mulDiv(twap,9951,10000)||uint256(current)>FullMath.mulDiv(twap,10049,10000))revert InvalidAction();
        uint256 swapIn=budget/2;
        (,uint256 platform,uint256 project)=ICreatorLiquidityHook(hook).quoteFees(swapIn,false,true);
        if(platform+project>=swapIn)revert InvalidAction();
        uint256 minOut=FullMath.mulDiv(FullMath.mulDiv(swapIn-platform-project,twap,uint256(1)<<96),twap,uint256(1)<<96);
        minOut=FullMath.mulDiv(minOut,99,100);
        uint160 limit=uint160(FullMath.mulDiv(twap,9951,10000));
        if(limit<=TickMath.MIN_SQRT_PRICE)limit=TickMath.MIN_SQRT_PRICE+1;
        if(limit>=current)revert InvalidAction();
        poolManager.swap(key,SwapParams(true,-int256(swapIn),limit),"");
        int256 tokenDelta=TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency1);
        int256 nativeDelta=TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency0);
        if(tokenDelta<=0||uint256(tokenDelta)<minOut||nativeDelta>=0||uint256(-nativeDelta)>=budget)revert InvalidAction();
        (current,,,) = StateLibrary.getSlot0(poolManager,key.toId());
        added=LiquidityAmounts.getLiquidityForAmounts(current,TickMath.getSqrtPriceAtTick(TickMath.minUsableTick(key.tickSpacing)),TickMath.getSqrtPriceAtTick(TickMath.maxUsableTick(key.tickSpacing)),budget-uint256(-nativeDelta),uint256(tokenDelta)+ownedTokenReserve);
        if(added==0)revert InvalidAction();
        (,BalanceDelta fees)=poolManager.modifyLiquidity(key,ModifyLiquidityParams(TickMath.minUsableTick(key.tickSpacing),TickMath.maxUsableTick(key.tickSpacing),int256(uint256(added)),bytes32(0)),"");
        if(fees.amount0()>0)poolManager.take(key.currency0,owner,uint256(uint128(fees.amount0())));
        if(fees.amount1()>0)poolManager.take(key.currency1,owner,uint256(uint128(fees.amount1())));
        tokenDelta=TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency1);
        if(tokenDelta<0){
            uint256 owed=uint256(-tokenDelta);if(owed>ownedTokenReserve)revert InvalidAction();
            ownedTokenReserve-=owed;poolManager.sync(key.currency1);
            if(!IERC20(token).transfer(address(poolManager),owed)||poolManager.settle()!=owed)revert InvalidAction();
        } else if(tokenDelta>0){uint256 received=uint256(tokenDelta);poolManager.take(key.currency1,address(this),received);ownedTokenReserve+=received;}
        nativeDelta=TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency0);
        if(nativeDelta>=0||uint256(-nativeDelta)>budget)revert InvalidAction();
        poolManager.burn(address(this),0,uint256(-nativeDelta));
        if(TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency0)!=0||TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency1)!=0)revert InvalidAction();
        liquidity+=added;
    }
    function _payAll(PoolKey memory key) private returns(uint256 nativeAmount,uint256 tokenAmount) {
        int256 a=TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency0);
        int256 b=TransientStateLibrary.currencyDelta(poolManager,address(this),key.currency1);
        if(a<0||b<0)revert InvalidAction();nativeAmount=uint256(a);tokenAmount=uint256(b);
        if(nativeAmount!=0)poolManager.take(key.currency0,owner,nativeAmount);
        if(tokenAmount!=0)poolManager.take(key.currency1,owner,tokenAmount);
    }
}
